<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { bindSkillTool, createSkill, createSkillVersion, listSkills, listTools, publishSkillVersion, type SkillSummary, type ToolSummary } from '@/api/admin-ai'
import { errorMessage } from '@/api/http'
import PageState from '@/components/PageState.vue'
import { confirmAction } from '@/composables/confirmation'
import { useAdminAuthStore } from '@/stores/admin-auth'
const auth = useAdminAuthStore(), items = ref<SkillSummary[]>([]), tools = ref<ToolSummary[]>([]), loading = ref(true), error = ref(''), notice = ref('')
const definition = reactive({ skill_code: '', display_name: '' })
const draft = reactive({ skill_id: '', instructions: '', input_schema: '{\n  "type": "object",\n  "additionalProperties": false\n}', output_schema: '{\n  "type": "object",\n  "additionalProperties": false\n}', evaluation_report: '{\n  "passed": false\n}' })
const binding = reactive({ skill_id: '', skill_version_no: 1, tool_code: '', tool_version_no: 1, permission_effect: 'allow', confirmation_policy: 'none', call_budget: 3, timeout_ms: 5000 })
const token = () => auth.accessToken!
async function load() { loading.value = true; try { const [skillList, toolList] = await Promise.all([listSkills(token()), listTools(token())]); items.value = skillList.data.items; tools.value = toolList.data.items } catch (cause) { error.value = errorMessage(cause) } finally { loading.value = false } }
async function addDefinition() { try { await createSkill(definition, token()); definition.skill_code = ''; definition.display_name = ''; notice.value = 'Skill Definition 已创建。'; await load() } catch (cause) { error.value = errorMessage(cause) } }
async function addVersion() { try { await createSkillVersion(draft.skill_id, { instructions: draft.instructions, input_schema: JSON.parse(draft.input_schema), output_schema: JSON.parse(draft.output_schema), evaluation_report: JSON.parse(draft.evaluation_report) }, token()); notice.value = '不可变 Skill 草稿版本已创建。'; await load() } catch (cause) { error.value = cause instanceof SyntaxError ? 'Schema 或评估报告不是有效 JSON。' : errorMessage(cause) } }
async function bindTool() { try { await bindSkillTool(binding.skill_id, binding.skill_version_no, { tool_code: binding.tool_code, tool_version_no: binding.tool_version_no, permission_effect: binding.permission_effect, confirmation_policy: binding.confirmation_policy, call_budget: binding.call_budget, timeout_ms: binding.timeout_ms }, token()); notice.value = '已将固定 Tool Version 与权限/预算绑定到 Skill 草稿。'; await load() } catch (cause) { error.value = errorMessage(cause) } }
async function publish(item: SkillSummary) { if (!item.latest_version || !await confirmAction('确认发起双人发布审批？只有评估报告通过的草稿可以提交。')) return; try { const result = (await publishSkillVersion(item.skill_id, item.latest_version, token())).data; notice.value = `审批 ${result.approval_request_id} 已创建，需 ${result.required_approval_count} 名独立管理员批准。`; await load() } catch (cause) { error.value = errorMessage(cause) } }
onMounted(load)
</script>
<template><section class="admin-page-stack"><header class="page-heading"><div><p class="eyebrow">Versioned Skill</p><h1>Skill 管理</h1><p class="muted">Instruction、Schema、评估、Tool Version、确认策略和调用预算固定到不可变版本。</p></div></header><p v-if="error" class="alert error">{{ error }}</p><p v-if="notice" class="alert success">{{ notice }}</p><div class="admin-split"><PageState :loading="loading" :error="''" :empty="!loading && items.length === 0" empty-title="暂无 Skill"><div class="card-list"><article v-for="item in items" :key="item.skill_id" class="card"><div class="card-heading"><div><h2>{{ item.display_name }}</h2><p>{{ item.skill_code }}</p></div><span class="badge">{{ item.status }}</span></div><p>最新 v{{ item.latest_version ?? '-' }} · 已发布 v{{ item.published_version ?? '-' }}</p><button v-if="auth.has('ai_skills:publish') && item.latest_version !== item.published_version" @click="publish(item)">发起发布审批</button></article></div></PageState><div v-if="auth.has('ai_skills:manage')" class="card-list"><form class="card admin-editor" @submit.prevent="addDefinition"><h2>新建 Definition</h2><label>Skill Code<input v-model="definition.skill_code" required></label><label>显示名称<input v-model="definition.display_name" required></label><button>创建</button></form><form class="card admin-editor" @submit.prevent="addVersion"><h2>新建不可变版本</h2><label>Skill<select v-model="draft.skill_id" required><option value="">请选择</option><option v-for="item in items" :key="item.skill_id" :value="item.skill_id">{{ item.display_name }}</option></select></label><label>Instructions<textarea v-model="draft.instructions" required></textarea></label><label>Input Schema<textarea v-model="draft.input_schema" required></textarea></label><label>Output Schema<textarea v-model="draft.output_schema" required></textarea></label><label>评估报告 JSON<textarea v-model="draft.evaluation_report" required></textarea></label><button>创建草稿版本</button></form><form class="card admin-editor" @submit.prevent="bindTool"><h2>绑定固定 Tool Version</h2><label>Skill<select v-model="binding.skill_id" required><option value="">请选择</option><option v-for="item in items" :key="item.skill_id" :value="item.skill_id">{{ item.display_name }}</option></select></label><label>Skill Version<input v-model.number="binding.skill_version_no" type="number" min="1" required></label><label>Tool<select v-model="binding.tool_code" required><option value="">请选择已发布 Tool</option><option v-for="item in tools" :key="item.tool_code">{{ item.tool_code }}</option></select></label><label>Tool Version<input v-model.number="binding.tool_version_no" type="number" min="1" required></label><label>Effect<select v-model="binding.permission_effect"><option value="allow">allow</option><option value="deny">deny（Hard Deny）</option></select></label><label>确认策略<select v-model="binding.confirmation_policy"><option value="none">none</option><option value="user_confirmation">user_confirmation</option><option value="required_approval">required_approval</option></select></label><div class="field-grid"><label>调用预算<input v-model.number="binding.call_budget" type="number" min="0" max="100"></label><label>超时 ms<input v-model.number="binding.timeout_ms" type="number" min="100" max="60000"></label></div><button>绑定 Tool</button></form></div></div></section></template>
